import stylesText from './amount-input.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { applyPreset, roundAmount, stepAmount, type AmountUnit } from '../../../../utils/amount-steps.js';
import { unitLabel } from '../../../../utils/line-view.js';
import { createAmountChangeEvent } from '../../health-events.js';

const styles = cssStyleSheet(stylesText);

const PRESETS = [0.5, 1.5, 2] as const;

const template = document.createElement('template');
template.innerHTML = `
    <div class="stepper">
        <button type="button" class="step" data-dir="-1" aria-label="Less">−</button>
        <input class="amount" inputmode="decimal" autocomplete="off" aria-label="Amount">
        <span class="unit"></span>
        <button type="button" class="step" data-dir="1" aria-label="More">+</button>
    </div>
    <div class="presets" hidden>
        ${PRESETS.map((f) => `<button type="button" class="preset" data-factor="${f}">x${f}</button>`).join('')}
    </div>
`;

/**
 * Story 420 — every amount field in the nutrition area (418): `−` input `+` on one line, stepping
 * through the unit's step list (419 review), optional ×0.5/×1.5/×2 presets that compound
 * (story 399). Never at or below 0; a field left empty or not a number is marked invalid and
 * emits nothing, so a save can't log 0.1 g (story 368).
 *
 *   <amount-input unit="g" presets></amount-input>   .value = 150
 *
 * `unit` is a food base unit or `factor` (a scale, shown as ×). Emits `health:amount-change`.
 */
export class AmountInput extends HTMLElement {
    static get observedAttributes() { return ['unit', 'presets', 'label']; }

    private current = 1;
    private readonly input: HTMLInputElement;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        this.input = shadow.querySelector('.amount') as HTMLInputElement;

        shadow.querySelectorAll<HTMLButtonElement>('.step').forEach((b) => b.addEventListener('click', () => {
            this.commit(stepAmount(this.unit, this.valid() ?? this.current, Number(b.dataset.dir) as 1 | -1));
        }));
        shadow.querySelectorAll<HTMLButtonElement>('.preset').forEach((b) => b.addEventListener('click', () => {
            this.commit(applyPreset(this.valid() ?? this.current, Number(b.dataset.factor)));
        }));
        this.input.addEventListener('input', () => {
            const typed = this.valid();
            this.input.toggleAttribute('aria-invalid', typed === null);
            if (typed !== null && typed !== this.current) {
                this.current = typed;
                this.dispatchEvent(createAmountChangeEvent({ value: typed }));
            }
        });
        // Leaving a field empty or wrong puts back the amount it holds (story 368).
        this.input.addEventListener('blur', () => this.render());
    }

    get unit(): AmountUnit {
        const u = this.getAttribute('unit');
        return u === 'ml' || u === 'piece' || u === 'factor' ? u : 'g';
    }

    get value(): number { return this.current; }
    set value(v: number) {
        if (!Number.isFinite(v) || v <= 0) throw new Error(`amount-input: ${v} is not an amount above 0`);
        this.current = roundAmount(v);
        this.render();
    }

    /** What is typed, when it is an amount above 0; `,` reads as a decimal point. */
    valid(): number | null {
        const n = Number(this.input.value.trim().replace(',', '.'));
        return this.input.value.trim() !== '' && Number.isFinite(n) && n > 0 ? roundAmount(n) : null;
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private commit(v: number): void {
        if (v === this.current) { this.render(); return; }
        this.current = v;
        this.render();
        this.dispatchEvent(createAmountChangeEvent({ value: v }));
    }

    private render(): void {
        const shadow = this.shadowRoot!;
        this.input.value = String(this.current);
        this.input.removeAttribute('aria-invalid');
        const label = this.getAttribute('label');
        this.input.setAttribute('aria-label', label ?? 'Amount');
        const unitEl = shadow.querySelector('.unit') as HTMLElement;
        unitEl.textContent = this.unit === 'factor' ? '×' : unitLabel(this.unit);
        (shadow.querySelector('.presets') as HTMLElement).hidden = !this.hasAttribute('presets');
        for (const b of shadow.querySelectorAll<HTMLButtonElement>('.step')) {
            const word = b.dataset.dir === '1' ? 'More' : 'Less';
            b.setAttribute('aria-label', label ? `${word} ${label}` : word);
        }
    }
}

if (!customElements.get('amount-input')) {
    customElements.define('amount-input', AmountInput);
}
