import { LINE_NUTRIENTS, type LineNutrient, type LineNutrition } from '@motivation/shared';
import { formatMacro } from './format-macro.js';

/**
 * A total over lines, per nutrient: the known sum, and whether some line did not know it.
 * Story 368: a partial total reads "150+?", and "?" when no line knew it — never 0.
 */
export type NutritionTotals = Record<LineNutrient, { value: number | null; partial: boolean }>;

export function totalsOf(lines: readonly LineNutrition[]): NutritionTotals {
    const out = {} as NutritionTotals;
    for (const n of LINE_NUTRIENTS) {
        const known = lines.map((l) => l[n]).filter((v): v is number => v !== null && Number.isFinite(v));
        out[n] = {
            value: known.length === 0 ? null : known.reduce((a, b) => a + b, 0),
            partial: known.length > 0 && known.length < lines.length,
        };
    }
    return out;
}

export function formatTotal(total: { value: number | null; partial: boolean }): string {
    if (total.value === null) return '?';
    return total.partial ? `${formatMacro(total.value)}+?` : formatMacro(total.value);
}
