import stylesText from './line-row.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { formatMacro, macroSegments } from '../../../../utils/format-macro.js';
import { unitLabel, viewNutrition, type LineView } from '../../../../utils/line-view.js';
import {
    HEALTH_EVENTS,
    createLineAmountChangeEvent,
    createLineOpenEvent,
    createLineRemoveEvent,
    type AmountChangeEvent,
} from '../../health-events.js';
import '../../food-thumbnail/food-thumbnail.component.js';
import '../provenance-badge/provenance-badge.component.js';
import '../amount-input/amount-input.component.js';
import type { AmountInput } from '../amount-input/amount-input.component.js';

const styles = cssStyleSheet(stylesText);

const REMOVE_SVG = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>`;

const template = document.createElement('template');
template.innerHTML = `
    <div class="row">
        <button type="button" class="open">
            <span class="time" hidden></span>
            <food-thumb></food-thumb>
            <span class="text">
                <span class="name"><span class="title"></span><provenance-badge hidden></provenance-badge></span>
                <span class="sub"></span>
            </span>
            <span class="kcal"></span>
        </button>
        <amount-input size="compact" hidden></amount-input>
        <button type="button" class="remove" hidden>${REMOVE_SVG}</button>
    </div>
`;

/**
 * Story 420 — one line, everywhere (418): the day's food, a meal's ingredient, a log's or a
 * draft's line. Read-only by default — tapping it emits `health:line-open`. `editable` puts its
 * `<amount-input>` on the row (`health:line-amount-change`), `removable` adds × (`health:line-remove`).
 * `time` leads the row on the day.
 */
export class LineRow extends HTMLElement {
    static get observedAttributes() { return ['editable', 'removable', 'time']; }

    private lineValue: LineView | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        // `amount-input` is set by property: upgrade it before its value can land as an own property.
        customElements.upgrade(shadow);
        shadow.querySelector('.open')!.addEventListener('click', () => {
            if (this.lineValue) this.dispatchEvent(createLineOpenEvent({ key: this.lineValue.key }));
        });
        shadow.querySelector('.remove')!.addEventListener('click', () => {
            if (this.lineValue) this.dispatchEvent(createLineRemoveEvent({ key: this.lineValue.key }));
        });
        // The input's own event stops here: a row speaks for its line.
        (shadow.querySelector('amount-input') as AmountInput).addEventListener(HEALTH_EVENTS.AMOUNT_CHANGE, (e: AmountChangeEvent) => {
            e.stopPropagation();
            if (this.lineValue) this.dispatchEvent(createLineAmountChangeEvent({ key: this.lineValue.key, amount: e.detail.value }));
        });
    }

    get line(): LineView | null { return this.lineValue; }
    set line(value: LineView) {
        this.lineValue = value;
        this.render();
    }

    /** False while an editable row's amount field holds something that is not an amount. */
    amountValid(): boolean {
        return !this.hasAttribute('editable') || (this.shadowRoot!.querySelector('amount-input') as AmountInput).valid() !== null;
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private render(): void {
        const shadow = this.shadowRoot!;
        const line = this.lineValue;
        if (!line) return;
        const editable = this.hasAttribute('editable');
        const n = viewNutrition(line);
        const amount = `${formatMacro(line.amount)} ${unitLabel(line.unit)}`;
        const macros = `P ${formatMacro(n.protein_g)} · C ${formatMacro(n.carbs_g)} · F ${formatMacro(n.fat_g)}`;

        const time = shadow.querySelector('.time') as HTMLElement;
        time.hidden = !this.hasAttribute('time');
        time.textContent = this.getAttribute('time') ?? '';
        const thumb = shadow.querySelector('food-thumb') as HTMLElement;
        if (line.imagePath) thumb.setAttribute('path', line.imagePath); else thumb.removeAttribute('path');
        (shadow.querySelector('.title') as HTMLElement).textContent = line.name;
        const badge = shadow.querySelector('provenance-badge') as HTMLElement;
        badge.hidden = line.badge === undefined;
        if (line.badge !== undefined) badge.setAttribute('kind', line.badge);
        // Editing, the amount is in the stepper; reading, it leads the subtitle.
        (shadow.querySelector('.sub') as HTMLElement).replaceChildren(...macroSegments(editable
            ? `${formatMacro(n.calories)} kcal · ${macros}`
            : `${amount} · ${macros}`));
        const kcal = shadow.querySelector('.kcal') as HTMLElement;
        kcal.hidden = editable;
        kcal.textContent = formatMacro(n.calories);

        const input = shadow.querySelector('amount-input') as AmountInput;
        input.hidden = !editable;
        input.setAttribute('unit', line.unit);
        input.setAttribute('label', line.name);
        if (input.value !== line.amount) input.value = line.amount;
        const remove = shadow.querySelector('.remove') as HTMLButtonElement;
        remove.hidden = !this.hasAttribute('removable');
        remove.setAttribute('aria-label', `Remove ${line.name}`);
        (shadow.querySelector('.open') as HTMLElement).setAttribute('aria-label', `${line.name}, ${amount}, ${formatMacro(n.calories)} kcal`);
    }
}

if (!customElements.get('line-row')) {
    customElements.define('line-row', LineRow);
}
